function initDataTable(){LoadGridData({tableId:"#dt_leads",url:globalvar.listingURL,columns:columnsConfig,extraParams:[{name:"searchText",value:$("#txtSearch").val()}]})}const columnsConfig=[{data:"FirstName",bSortable:!0},{data:"LastName",bSortable:!0},{data:"Email",bSortable:!0},{data:"PhoneNumber",bSortable:!1},{data:"CompanyID",bSortable:!1},{data:"PolicyTypeID",bSortable:!1},{data:"InquiryDate",bSortable:!0,render:function(n){return n?moment(n).format("MM/DD/YYYY hh:mm A"):""}},{data:"NextFollowUpDate",bSortable:!0,render:function(n){return n?moment(n).format("MM/DD/YYYY hh:mm A"):""}},{data:"LeadSource",bSortable:!1},{data:"LeadStatus",bSortable:!1},{title:"Actions",bSortable:!1,width:"170px",defaultContent:"",className:"text-center",render:function(n,t,i){let r=parseInt(i.LeadID,10);return'<a href="/Leads/Edit/'+r+'" class="btn btn-sm btn-icon btn-lg-light btn-text-primary btn-hover-light-primary mr-3"><i class="flaticon-edit"><\/i><\/a><a href="javascript:;" class="btn btn-sm btn-icon btn-lg-light btn-text-danger btn-hover-light-danger" onclick="DeleteConfirmationWithTypeDelete('+r+",'Lead','Lead')\"><i class=\"flaticon-delete\"><\/i><\/a>"}}];$(function(){globalvar.IsformView||initDataTable();parseInt(globalvar.rowsaffected)>0?toastr.success(globalvar.tostarMsg):parseInt(globalvar.rowsaffected)==0&&toastr.error(globalvar.tostarMsg)});$("#txtSearch").on("keyup",function(){initDataTable()});